import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"用語辞典","description":"","frontmatter":{},"headers":[],"relativePath":"ja/0090-术语词典.md","filePath":"ja/0090-术语词典.md"}'),l={name:"ja/0090-术语词典.md"};function i(o,t,h,n,s,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="用語辞典" tabindex="-1">用語辞典 <a class="header-anchor" href="#用語辞典" aria-label="Permalink to &quot;用語辞典&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>90</td></tr><tr><td>所属モジュール</td><td>付録と参考資料</td></tr><tr><td>コアキーワード</td><td>用語辞典、核心概念、定義、統一用語、衡元宙</td></tr></tbody></table><h2 id="第一節-用語説明" tabindex="-1">第一節 用語説明 <a class="header-anchor" href="#第一節-用語説明" aria-label="Permalink to &quot;第一節 用語説明&quot;">​</a></h2><p>本辞典は、アンカー共生文明設定体系における核心用語を収録し、全文書における用語使用を統一し、概念表現の一致性と正確性を確保することを目的とする。すべての用語はピンインの頭文字順に配列され、各用語には用語名、英語参考名（ある場合）、定義と簡単な説明が含まれる。本辞典は動的更新文書であり、設定体系の拡張に伴い新しい用語が継続的に追加される。</p><h2 id="第二節-核心用語表" tabindex="-1">第二節 核心用語表 <a class="header-anchor" href="#第二節-核心用語表" aria-label="Permalink to &quot;第二節 核心用語表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>番号</th><th>用語</th><th>定義と説明</th></tr></thead><tbody><tr><td>1</td><td>アンカー</td><td>法則ネットワークにおける安定ノードであり、位面法則の安定を維持し、跨位面接続と時間遡行を実現するための座標基準である。アンカーは本質的に宇宙本源法則が特定の空間位置において高密度に凝縮したものであり、自己維持と校正能力を備えている。</td></tr><tr><td>2</td><td>アンカー共生文明</td><td>アンカー機構を技術基盤とし、共生進化を核心理念とする文明形態。略奪式修練体系に反対し、運命と進化の選択権を衆生に返還し、多労多得、自生自長、人人有路、万族共進を実現することを主張する。</td></tr><tr><td>3</td><td>衡元宙</td><td>「万霊衡锚本源宙」の略称であり、アンカー共生文明が居住し治理する宇宙全域である。物質位面、エネルギー層、意識域、法則ネットワークの四つの層級から共同で構成される複合存在体である。</td></tr><tr><td>4</td><td>万霊衡锚本源宙</td><td>衡元宙の全称。「万霊」は知覚と進化の潜在能力を備えるすべての生命形態を指し、「衡锚」は宇宙の平衡を維持するアンカー機構を指し、「本源宙」は本源法則を根基とし共生進化を方向とする本質属性を強調する。</td></tr><tr><td>5</td><td>共生</td><td>アンカー共生文明の核心理念の一つであり、異なる生命個体、種族と文明の間が互恵協力を通じて共同進化を実現することを指し、他人を犠牲にする略奪式進化ではない。</td></tr><tr><td>6</td><td>略奪式修練体系</td><td>弱者のエネルギー、気運さらには本源を吞噬することで自身の進化を実現する修練方式。アンカー共生文明が断固として反対する体系類型であり、宇宙エントロピーの加速増加と文明断層の多発を引き起こす根源であるとされる。</td></tr><tr><td>7</td><td>三百套本源修練体系</td><td>宇宙本源法則から直接抽出され、アンカーにより検証された正統な修練経路であり、計三百套あり、本源推演類、生命循環類、空間法理類、意識昇維類、共生ネットワーク類、応用工程類の六大類に分けられ、各類五十套である。</td></tr><tr><td>8</td><td>本源三基</td><td>三百套体系中の前三套の基礎体系——推演迭代体系（第1套）、生命循環体系（第2套）、空間法理調度体系（第3套）であり、他のすべての体系の修練基礎である。</td></tr><tr><td>9</td><td>推演迭代体系</td><td>第1套本源修練体系であり、百倍修練推演増幅を核心特徴とし、倍増果実の技術化応用を借りて推演能力を百倍に向上させ、推演、検証、迭代を通じて修練経路を最適化することを強調する。</td></tr><tr><td>10</td><td>生命循環体系</td><td>第2套本源修練体系であり、生命エネルギーの良性循環を核心とし、修練者自身と環境の間のエネルギー交換が循環式であり略奪式ではないことを強調する。</td></tr><tr><td>11</td><td>空間法理調度体系</td><td>第3套本源修練体系であり、空間法則の理解と調度を核心とし、跨位面インタラクション、隔離空間構築、複製鏡技術などの重要な応用の修練基礎である。</td></tr><tr><td>12</td><td>倍増果実</td><td>ワンピース世界に由来する倍増果実であり、衡元宙において技術化応用され、修練者の推演能力を百倍に向上させることができ、推演迭代体系の核心補助ツールである。開局バフの一つ。</td></tr><tr><td>13</td><td>聯産承包機制</td><td>アンカー共生文明の資源分配機制であり、宇宙修練資源を「承包」の方式で個体または群体に分配し、承包者は労働と貢献を通じて資源使用権を獲得し、多労多得を実現する。</td></tr><tr><td>14</td><td>20%活性化戦略</td><td>アンカー共生文明の段階的戦略目標であり、前期に全宇宙20%の衆生を位面至高強者に活性化し、これらを骨幹として残り80%の衆生の共同進化を牽引する。</td></tr><tr><td>15</td><td>位面至高強者</td><td>修練が極めて高い境地に達し、独力で一個の位面法則の安定を維持できる強者。20%活性化戦略の目標養成対象であり、アンカーネットワークの重要な維護力量でもある。</td></tr><tr><td>16</td><td>法則ネットワーク</td><td>衡元宙構造の第四層級であり、宇宙本源法則の運行底層でありアンカーの根基層である。法則ネットワークは宇宙全体を貫き、すべての法則操作（空間調度、時間遡行、エネルギー転換を含む）の技術基盤である。</td></tr><tr><td>17</td><td>位面</td><td>相対的に安定した法則集合により界定された、独立した時空連続性を備える存在区域。各々の位面は独特の物理定数、エネルギー密度、時間流速と意識活跃度を有する。</td></tr><tr><td>18</td><td>法則壁</td><td>隣接する位面を隔てる法則障壁であり、その強度は隣接位面間の法則パラメータの差異程度に依存する。位面穿梭には法則壁を克服する必要がある。</td></tr><tr><td>19</td><td>法則指紋</td><td>各々の位面の核心法則パラメータをハッシュ演算して生成される唯一の標識であり、長さは128ビットであり、位面座標体系の核心パラメータの一つである。</td></tr><tr><td>20</td><td>先観測後有限干渉</td><td>時間遡行と跨位面考古の首要操作原則であり、いかなる遡行または考古もまず純観測段階を完成し、重大なリスクがないことを確認した後に初めて有限度の干渉を行うことができると要求する。</td></tr><tr><td>21</td><td>複製鏡</td><td>空間法理法則に基づく高精度複製装置であり、原物に接触することなく目標区域に対して1:1完全複製を行うことができ、異地考古方案の核心設備である。</td></tr><tr><td>22</td><td>隔離空間</td><td>空間法理調度技術を通じて構築された独立法則区域であり、考古副本を搭載し考古人員の作業場所として使用され、外部宇宙とは法則壁により完全に隔離されている。</td></tr><tr><td>23</td><td>僅回伝知識</td><td>考古協議の核心原則であり、考古過程において目標対象から取得するものは抽象的な知識と情報のみであり、いかなる物質、エネルギーまたは生命体も回伝してはならないことを指す。</td></tr><tr><td>24</td><td>情報純化</td><td>原始情報に携帯された来源位面の法則印跡を徹底的に剥離し、純粋な意味内容のみを保留する技術過程であり、回伝知識の安全性を確保するための鍵となる環節である。</td></tr><tr><td>25</td><td>時間パラドックス</td><td>時間遡行操作において干渉行為により因果論理に自己矛盾が生じる現象であり、弑祖パラドックス、情報パラドックス、本体パラドックスと事象パラドックスの四大類を含む。</td></tr><tr><td>26</td><td>因果鎖</td><td>事件間の前因後果の連続的な線形構造であり、時間法則の核心概念である。時間遡行操作の核心リスクは因果鎖に対する擾動である。</td></tr><tr><td>27</td><td>共生憲法</td><td>アンカー共生文明の根本大法であり、最高の法的効力を有し、反略奪・倡共生の文明底色と七大憲法基本原則を確立する。</td></tr><tr><td>28</td><td>万族平等</td><td>共生憲法七大基本原則の一つであり、すべての生命形態は種族、修為、出身を問わず、法律の面前で一律に平等であることを指す。</td></tr><tr><td>29</td><td>奇特生命</td><td>常規の生命定義に合致せず、特殊な存在形態を備える生命形式であり、三類標準化処置流程に従って識別と管理を行う必要がある。</td></tr><tr><td>30</td><td>奇異エネルギー</td><td>常規のエネルギー分類に合致せず、特殊な属性と行為モードを備えるエネルギー形式であり、三類標準化処置流程に従って分類と管控を行う必要がある。</td></tr><tr><td>31</td><td>暗黒置換体</td><td>一種の特殊な生命形態であり、双魂共存の倫理問題に関わり、双魂倫理準則と四類分支処置規則に従って管理を行う必要がある。</td></tr><tr><td>32</td><td>双魂倫理</td><td>暗黒置換体における二つの魂の共存状態に対する倫理準則であり、核心は二つの魂の各自の権利を尊重し、強制融合または一方の消滅を禁止することである。</td></tr><tr><td>33</td><td>五種共生文明分型</td><td>現実世界の文明特徴に基づいて划分された五種の共生社会類型：東アジア集約型、北欧福利型、北米多元型、ヨーロッパ大陸社会型、発展中趕超型。</td></tr><tr><td>34</td><td>四階段昇維経路</td><td>衡元宙宇宙全体の昇維における四階段ルート：現実築基→科技賦能→意識進化→星際共生。</td></tr><tr><td>35</td><td>現実為基</td><td>アンカー共生文明の根本立場の一つであり、現実世界が唯一の真実世界であり、小説世界は虚偽の思想実験であり、虚構の不足は現実で補充し、現実にないものは法則に基づいて昇級創造することを指す。</td></tr><tr><td>36</td><td>共生度</td><td>一つの文明または個体が共生ネットワークと融合する程度を評価する量化指標であり、資源共有度、協作頻度、利他行為比例などの複数の次元をカバーする。</td></tr><tr><td>37</td><td>アンカー議事会</td><td>アンカー共生文明の最高権力機構であり、万族代表が比例により構成され、立法権と重大事項決定権を行使する。</td></tr><tr><td>38</td><td>共生執行委員会</td><td>アンカー共生文明の最高行政機構であり、憲法と法律の執行、日常治理を担当する。</td></tr><tr><td>39</td><td>共生法院</td><td>アンカー共生文明の最高司法機構であり、独立して審判権を行使し、違憲審査と重大案件の審理を担当する。</td></tr><tr><td>40</td><td>位面管理局</td><td>アンカー議事会の下属する専門機構であり、位面座標総庫の維護、穿梭許可の審批、跨位面考古管理などの事務を担当する。</td></tr></tbody></table><h2 id="第三節-用語使用規範" tabindex="-1">第三節 用語使用規範 <a class="header-anchor" href="#第三節-用語使用規範" aria-label="Permalink to &quot;第三節 用語使用規範&quot;">​</a></h2><ol><li>本辞典に収録された用語は標準用語であり、すべての文書は本辞典中の標準表現を優先的に使用すべきである。</li><li>同一の概念は異なる文書において同一の用語を使用しなければならず、随意に同義語を交換してはならない。</li><li>新しい設定において生まれた新しい用語は、速やかに用語委員会に審査を提出し、審査に通過した後に本辞典に追加する。</li><li>用語の定義に修訂が生じた場合は、本辞典の最新バージョンを基準とし、同時に文書バージョン説明に修訂内容を記録しなければならない。</li><li>用語を引用する際、初出時は全称を使用し、後続は略称を使用してもよいが、文脈における意味が明確であることを確保しなければならない。</li></ol><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>用語辞典は設定体系全体の言語的基石である。統一された用語体系は百份の文書間の概念一致性を確保し、読者が異なるモジュール間を理解の曖昧さなしにシームレスに切り替えることを可能にする。設定体系が不断に豊かになり完善されるに伴い、本辞典は継続的に更新され、常にすべての文書の用語権威来源として機能する。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>00-衡元宙宇宙総覧</li><li>02-アンカー本源定義と本質</li><li>99-文書バージョンと維護説明</li></ul>',12)])])}const u=d(l,[["render",i]]);export{b as __pageData,u as default};
